export async function mapLimit(items, limit, mapper) {
  if (limit <= 0) {
    throw new Error("limit must be positive");
  }

  const results = new Array(items.length);
  const errors = new Array(items.length);
  const pending = new Set();
  let hasError = false;

  const processItem = async (index) => {
    if (hasError) return;

    try {
      const result = await mapper(items[index], index);
      results[index] = result;
    } catch (error) {
      hasError = true;
      errors[index] = error;
    } finally {
      pending.delete(index);
      // Process next item if available
      if (!hasError) {
        const nextIndex = findNextIndex();
        if (nextIndex !== -1) {
          pending.add(nextIndex);
          processItem(nextIndex);
        }
      }
    }
  };

  const findNextIndex = () => {
    for (let i = 0; i < items.length; i++) {
      if (results[i] === undefined && errors[i] === undefined && !pending.has(i)) {
        return i;
      }
    }
    return -1;
  };

  // Start up to `limit` items
  for (let i = 0; i < items.length && i < limit; i++) {
    pending.add(i);
    processItem(i);
  }

  // Wait for all pending items to complete
  await Promise.all(Array.from(pending).map(index => {
    return new Promise((resolve, reject) => {
      const checkComplete = () => {
        if (results[index] !== undefined || errors[index] !== undefined) {
          if (errors[index]) {
            reject(errors[index]);
          } else {
            resolve();
          }
        } else {
          setTimeout(checkComplete, 0);
        }
      };
      checkComplete();
    });
  }));

  if (hasError) {
    throw errors.find(error => error !== undefined);
  }

  return results;
}

