    for (let i = 0; i < items.length; i++) {
      if (!executing.has(i) && !error) {
        return processItem(i);
      }
    }
  };

  const promises = [];
  for (let i = 0; i < Math.min(limit, items.length); i++) {
    promises.push(startNext());
  }

  await Promise.all(promises);

  if (error) {
    throw error;
  }

  return results;
}

